const trustedAgeScope=clone(data.ageScope),scopeProtectedIds=new Set(Object.keys({...data.inheritedSources,...data.registrySources}));
function scopeResult(original,p,key){
 if(key!=='pps_61')return null;
 const age=typeof p.age==='string'&&p.age?p.age:'unknown',row=trustedAgeScope.eligibilityByExistingAgeBand.find(r=>r.ageBand===age);
 if(!row||row.specificBodyAllowed)return null;
 const message=trustedAgeScope.messages[row.familyMessageId],sections=[clone(message),...clone(trustedAgeScope.messages.safety_for_scope_responses)];
 return {ok:true,mode:'review',topic:null,requestedTopic:key,renderedTopic:null,specificBodyAllowed:false,priority:'routine_review',bodyDecision:row.decision,reasonCode:row.reasonCode,label:message.title,missingFields:age==='unknown'?['age']:[],sections,refs:[...new Set([...(original.refs||[]).filter(id=>scopeProtectedIds.has(id)),...trustedAgeScope.evidenceRefsByAge[age]])],text:trustedAgeScope.scopeTexts[row.familyMessageId],warnings:[]};
}
