root.PaisDermatitisCommonLoadStatus={ready,fallbackActive:!ready,expectedClinicalCompiledSha256:data.clinicalCompiledSha256,loadedClinicalCompiledSha256:loaded?.data?.clinicalCompiledSha256||null};
if(ready||!base)return;
const trustedSources=clone({...data.inheritedSources,...data.registrySources}),baseline=new Map(data.variants.map(r=>[r.key+'|'+r.age,r.result]));
