function validAge(p){const a=p.age===undefined||p.age===null||p.age===''?'unknown':p.age;return typeof a==='string'&&Object.hasOwn(base.ages,a);}
function invalidAge(){return {ok:false,code:'AGE_INVALID',message:'Selecione uma faixa etária válida.',error:'Selecione uma faixa etária válida.'};}

