function contextMismatch(message){const error=Error(message);error.contextMismatch=true;throw error;}
function replaceBody(original,p,t){const prior=baseline.get(t.key+'|'+(p.age||'unknown')),sections=clone(t.sections),remaining=new Map(prior.sections.map(s=>[s.title,[...s.items]])),extras=[];
 for(const s of original.sections){if(s.title==='COMPLEMENTO DA CONSULTA'){extras.push({title:s.title,items:[...s.items]});continue;}if(!remaining.has(s.title))contextMismatch('Unexpected inherited section');const ordinary=remaining.get(s.title),items=[];for(const item of s.items){const at=ordinary.indexOf(item);if(at>=0)ordinary.splice(at,1);else items.push(item);}if(items.length)extras.push({title:s.title,items});}
 if([...remaining.values()].some(items=>items.length))contextMismatch('Missing inherited ordinary content');
 const pps=t.key.startsWith('pps_'),a=pps?trusted.appendix.pps:trusted.appendix.ext,follow=sections.find(s=>s.id==='follow');let returnItem=null,riskItem=null,notes=null;const care=[],alarms=[];
 for(const e of extras){if(e.title==='COMPLEMENTO DA CONSULTA'){if(notes)contextMismatch('Duplicate notes section');notes=e;continue;}for(const item of e.items){
  if(e.title==='QUANDO REAVALIAR'&&item.startsWith(a.returnPrefix)){if(returnItem)contextMismatch('Duplicate return plan');returnItem=item;}
  else if(e.title==='QUANDO REAVALIAR'&&item===a.risk){if(riskItem)contextMismatch('Duplicate risk item');riskItem=item;}
  else if(e.title==='MEDIDAS SEM REMÉDIOS'&&a.care.includes(item)){if(!care.includes(item))care.push(item);}
  else if(e.title===a.alarmTitle&&a.alarms.includes(item)){if(!alarms.includes(item))alarms.push(item);}
  else contextMismatch('Unrecognized inherited appendix');}}
 const refs=[...new Set([...original.refs,...t.refs])],addRefs=ids=>{for(const id of ids)if(!refs.includes(id))refs.push(id);};
 if(alarms.length){const at=sections.findIndex(s=>s.id==='urgent');sections.splice(at+1,0,{id:'contextual-urgent',title:a.alarmDestinationTitle,items:alarms,itemIds:alarms.map((_,i)=>t.key+'.contextual-urgent.'+(i+1))});}
 if(care.length){const at=sections.findIndex(s=>s.id==='home');sections.splice(at+1,0,{id:'contextual-care',title:'CUIDADOS PARA OUTROS SINAIS INFORMADOS',items:care,itemIds:care.map((_,i)=>t.key+'.contextual-care.'+(i+1))});}
 if(care.includes(a.nasalItem))addRefs(trusted.contextRefs.nasal);
 if(pps&&care.includes(a.nebulizationItem))addRefs(trusted.contextRefs.ppsNebulization);
 if(care.includes(a.gastrointestinalItem)||alarms.length)addRefs(trusted.contextRefs.gastrointestinal);
 const entries=[];if(pps){if(returnItem)entries.push([returnItem,t.key+'.contextual-return']);if(riskItem)entries.push([riskItem,t.key+'.contextual-risk']);follow.items.unshift(...entries.map(x=>x[0]));follow.itemIds.unshift(...entries.map(x=>x[1]));}
 else{if(riskItem)entries.push([riskItem,t.key+'.contextual-risk']);if(returnItem)entries.push([returnItem,t.key+'.contextual-return']);follow.items.push(...entries.map(x=>x[0]));follow.itemIds.push(...entries.map(x=>x[1]));}
 if(notes)sections.push({id:'contextual-notes',title:notes.title,items:notes.items,itemIds:notes.items.map((_,i)=>t.key+'.contextual-notes.'+(i+1))});
 if(refs.some(id=>!Object.hasOwn(protectedSources,id)))contextMismatch('Unexpected reference');sections.forEach((s,i)=>s.number=i+1);return {...original,sections,refs,text:textFor(t.label,sections,p.age||'unknown')};
}
function bootstrapValid(){try{return bootstrapSourcesValid&&fingerprint(data)==='99fbd84fb8e825a4a1e159611b5d46117c779956e4e50d32f61773252c859da3'&&base.topics.length===trusted.topicCount&&trusted.originalTopics.every(t=>canonical(base.topics.find(x=>x.key===t.key))===canonical(t));}catch(_){return false;}}

