 const pps=t.key.startsWith('pps_'),family=pps?'pps':t.key==='ext_dorabdominal'?'abdominal':'colicMesenteric',a=trusted.appendix[family],follow=sections.find(s=>s.id==='follow');let returnItem=null,riskItem=null,notes=null;const care=[],alarms=[];
